        for i in range(self.dim):
            for j in range(i+1, self.dim):
                f_value += 0.4 * np.sin(11 * x[i]) * np.cos(16 * x[j]) * np.sin(13 * x[i] + 7 * x[j]) * np.cos(9 * x[i] - 6 * x[j]) * np.sin(12 * x[i] + 4 * x[j])

